insert into public.konten(id_poi,bahasa,profil,teks_cerita,judul_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000001','id','umum','Jutaan tahun lalu, Indonesia dihuni berbagai hewan purba berukuran unik! Ada Megalochelys sp., kura-kura raksasa, hingga Elephas celebensis, gajah purba mungil dari Sulawesi. Bersama Elephas maximus dan Sinomastodon bumiayuensis, fosil-fosil ini menjadi saksi beragamnya kehidupan fauna di masa lalu. Yuk, amati dan temukan perbedaannya!','Debaran Fauna Purba Indonesia','Elephas celebensis dikenal sebagai salah satu gajah purba berukuran kecil yang pernah hidup di Sulawesi.','Megalochelys sp., Elephas celebensis, Elephas maximus, Sinomastodon bumiayuensis')
insert into public.konten(id_poi,bahasa,profil,teks_cerita,judul_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000002','id','umum','Pernah melihat gua dengan hiasan batu yang menjuntai dari langit-langitnya? Itulah salah satu keunikan kawasan karst, seperti Gunung Sewu, yang terbentuk melalui proses pelarutan batuan kapur selama waktu yang sangat lama. Yuk, amati stalaktit, sinter kapur, batu jahe, hingga berbagai jenis batuan dan terumbu karang untuk mengenal keindahan proses pembentukan alam!','Rahasia Dunia Karst Indonesia','Stalaktit terbentuk dari endapan mineral kalsit yang menumpuk perlahan dari tetesan air di langit-langit gua.','Karst Gunung Sewu, stalaktit kalsit, batugamping, batu jahe, sinter kapur, marmer, amfibolit, hasil karstifikasi, hard coral, plate coral, branching coral, head coral')
insert into public.konten(id_poi,bahasa,profil,teks_cerita,judul_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000004','id','umum','Tahukah kamu bahwa bentuk muka bumi Indonesia terbentuk melalui proses geologi selama jutaan tahun? Pergerakan dan tekanan lempeng bumi menghasilkan berbagai struktur batuan, seperti lipatan dan sesar. Yuk, amati koleksi genes, sekis biotit, serta contoh struktur geologi untuk melihat bagaimana bumi terus berubah!','Kisah Terbentuknya Muka Bumi Indonesia','Lipatan terbentuk ketika lapisan batuan mendapat tekanan hingga melengkung tanpa terpecah.','Genes, sekis biotit, lipatan, sesar')
insert into public.konten(id_poi,bahasa,profil,teks_cerita,judul_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000005','id','umum','Pernah penasaran bagaimana ribuan pulau di Indonesia terbentuk? Melalui animasi ini, kamu bisa mengikuti perjalanan terbentuknya Kepulauan Indonesia akibat pergerakan lempeng tektonik, aktivitas gunung api, dan proses geologi selama jutaan tahun. Yuk, saksikan bagaimana daratan yang awalnya terpisah akhirnya membentuk Indonesia seperti yang kita kenal sekarang!','Perjalanan Lahirnya Kepulauan Indonesia','Bentuk kepulauan Indonesia terus mengalami perubahan akibat aktivitas tektonik hingga saat ini.','video')
insert into public.konten(id_poi,bahasa,profil,teks_cerita,judul_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000006','id','umum','Bentuk permukaan bumi yang kita lihat sekarang terbentuk melalui proses alam selama ribuan hingga jutaan tahun. Pelapukan menghancurkan batuan, erosi memindahkan material, sedangkan pengendapan menumpuknya di tempat baru. Yuk, amati contoh bentukan muka bumi dan cari tahu bagaimana ketiga proses ini mengubah lanskap Indonesia!','Bagaimana Wajah Bumi Terbentuk?','Material hasil erosi dapat terbawa air, angin, maupun es sebelum akhirnya mengendap di tempat lain.','Sembulan bentukan morfologi muka bumi, pelapukan, erosi, dan pengendapan')
insert into public.konten(id_poi,bahasa,profil,teks_cerita,judul_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000007','id','umum','Bumi menyimpan beragam mineral dan batuan dengan warna, bentuk, serta karakteristik yang berbeda! Ada lapis lazuli yang terkenal dengan warna biru pekatnya, hingga geodes yang menyimpan kristal di bagian dalamnya. Yuk, amati berbagai koleksi mineral dan kenali tiga kelompok utama batuan: beku, sedimen, dan metamorf!','Mengenal Harta Karun Bumi: Batuan dan Mineral','eodes dapat terlihat seperti batu biasa dari luar, tetapi bagian dalamnya bisa dipenuhi kristal yang indah.','Lapis lazuli, mineral hidroksida, oksida, silikat, karbonat, borat dan nitrat, unsur asli (native elements), sulfida, fosfat, sulfat, batuan beku, batuan sedimen, batuan metamorf, geodes')
insert into public.konten(id_poi,bahasa,profil,teks_cerita,judul_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000008','id','umum','Permukaan bumi yang kita pijak ternyata terus bergerak! Tenaga tektonik berasal dari pergerakan lempeng bumi yang dapat membentuk pegunungan, lipatan, hingga patahan. Yuk, amati koleksi sekis mika, peridotit, dan lava basal untuk mengenal lebih jauh proses yang membentuk bumi!','Kekuatan Tersembunyi di Dalam Bumi','Peridotit merupakan batuan yang banyak menyusun bagian mantel atas bumi.','Proses terjadinya tenaga tektonik, sekis mika, peridotit, lava basal')
insert into public.konten(id_poi,bahasa,profil,teks_cerita,judul_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000009','id','umum','Pernah membayangkan bagaimana alam semesta dan planet Bumi terbentuk? Menurut teori Big Bang, alam semesta bermula dari kondisi yang sangat panas dan padat, lalu terus mengembang hingga sekarang. Seiring waktu, Bumi terbentuk dan mengalami perubahan struktur serta bentuk hingga menjadi planet yang kita kenal saat ini. Yuk, ikuti perjalanan panjang Bumi melalui koleksi dan ilustrasi di hadapanmu!','Dari Big Bang hingga Terbentuknya Bumi','Bumi memiliki empat lapisan utama, yaitu kerak, mantel, inti luar, dan inti dalam.','Teori Big Bang, hamparan luas alam semesta, proses terbentuknya planet Bumi, penampang struktur Bumi, perkembangan bentuk Bumi')
insert into public.konten(id_poi,bahasa,profil,teks_cerita,judul_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000010','id','umum','Indonesia memiliki beragam jenis batuan yang terbentuk melalui proses geologi yang berbeda-beda. Mulai dari batugamping hitam, sekis biotit, rijang, peridotit, hingga granit, setiap batuan menyimpan cerita tentang proses pembentukan bumi. Yuk, amati warna dan tekstur koleksinya, lalu temukan perbedaannya!','Ragam Batuan dari Nusantara','Granit terbentuk dari magma yang mendingin secara perlahan di bawah permukaan bumi sehingga kristalnya dapat terlihat jelas.','Batugamping hitam, sekis biotit, rijang, peridotit, batuan granit')
insert into public.konten(id_poi,bahasa,profil,teks_cerita,judul_cerita,fakta_menarik,koleksi_sorotan) values ('30000000-0000-4000-8000-000000000011','id','umum','Indonesia menyimpan kekayaan geologi yang melimpah, mulai dari mineral logam, mineral non-logam, hingga batu mulia seperti ametis dari Solok, Sumatera Barat. Selain itu, ada batubara, minyak dan gas bumi, panas bumi, serta sumber daya air yang dimanfaatkan untuk kehidupan sehari-hari. Yuk, kenali berbagai potensi alam ini dan bagaimana manusia memanfaatkannya!','Kekayaan Indonesia','Indonesia memiliki potensi panas bumi yang besar karena berada di kawasan dengan aktivitas vulkanik tinggi.','Batubara, mineral logam, mineral non-logam, batu mulia (ametis), minyak dan gas bumi, panas bumi (geothermal), sumber daya air dan cekungan air tanah')
